      "id": "R1",
      "type": "PROCESS",
      "otherName": "",
      "reason": "mRNA로 전사된 산출물이 다음 단계에서 세포질로 이동하는 순서를 나타낸다."
    },
    {
      "id": "R2",
      "type": "PROCESS",
      "otherName": "",
      "reason": "세포질로 이동한 mRNA를 바탕으로 단백질 합성이 진행되는 단계적 관계이다."
    },
    {
      "id": "R3",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "mRNA와 리보솜을 통한 단백질 합성 원리를 바이러스의 숙주 이용 현상에 가져다 설명한다."
    },
    {
      "id": "R4",
      "type": "CAUSE",
      "otherName": "",
      "reason": "숙주에서 합성된 바이러스 단백질이 생물체의 항원 인식을 일으키는 실제 작용 관계이다."
    },
    {
      "id": "R5",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "바이러스에 대한 면역 반응 원리를 인공적으로 바이러스를 흉내 낸 백신의 예방 효과에 적용한다."
    },
    {
      "id": "R6",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "백신의 면역 유도 설명을 mRNA 백신이라는 구체적 사례의 작동 방식으로 상세화한다."
    },
    {
      "id": "R7",
      "type": "CAUSE",
      "otherName": "",
      "reason": "바이러스 단백질의 합성이 실제로 면역 반응을 유발하는 관계이다."
    },
    {
      "id": "R8",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "접종 물질이 바이러스인지라는 같은 기준에서 기존 백신과 mRNA 백신의 차이를 제시한다."
    },
    {
      "id": "R9",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "mRNA 백신이 바이러스가 아니라는 사실을 근거로 바이러스 감염 위험이 없다는 판단을 도출한다."
    },
    {
      "id": "R10",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "체내 효소에 쉽게 분해된다는 성질을 체내에서 불안정하다는 말로 다시 표현한다."
    },
    {
      "id": "R11",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "동일한 mRNA 백신의 안전성이라는 장점에 불안정성과 낮은 흡수율이라는 한계를 덧붙인다."
    },
    {
      "id": "R12",
      "type": "CAUSE",
      "otherName": "",
      "reason": "큰 분자 크기가 세포 흡수를 어렵게 하는 물리적 원인으로 제시된다."
    },
    {
      "id": "R13",
      "type": "CAUSE",
      "otherName": "",
      "reason": "mRNA의 음전하가 세포막과의 반발 등을 통해 세포 흡수를 저해하는 실제 원인이다."
    },
    {
      "id": "R14",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "mRNA의 불안정성과 낮은 세포 흡수율이라는 문제에 지질 나노 입자라는 전달 장치를 제시한다."
    },
    {
      "id": "R15",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "지방산으로 이루어졌다는 구성상의 사실을 근거로 지질이 소수성을 갖는다고 설명한다."
    },
    {
      "id": "R16",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "친수성·소수성 물질의 혼합 원리가 앞서 제시한 지질의 소수성을 뒷받침하는 설명 근거이다."
    },
    {
      "id": "R17",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "어떤 물질과 섞이는지라는 같은 기준에서 물과 소수성 물질의 성질을 대비한다."
    },
    {
      "id": "R18",
      "type": "CAUSE",
      "otherName": "",
      "reason": "인지질의 친수성·소수성 성질이 세포막의 배열과 투과 차단 특성을 형성하는 실제 작용을 설명한다."
    },
    {
      "id": "R19",
      "type": "CAUSE",
      "otherName": "",
      "reason": "소수성 꼬리가 모인 세포막 구조가 친수성 물질의 투과를 실제로 차단한다."
    },
    {
      "id": "R20",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "지질 나노 입자를 이용한다는 설명을 양이온성 지질의 전기적 반발 방지 방식으로 구체화한다."
    },
    {
      "id": "R21",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "세포막을 구성하는 인지질의 인산기 머리가 음전하를 띤다는 동일한 내용을 다시 제시한다."
    },
    {
      "id": "R22",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "인산기 머리와 반발하지 않는다는 사실이 양이온성 지질의 반발력 방지 효과를 뒷받침하는 근거로 제시된다."
    },
    {
      "id": "R23",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "동일한 양이온성 지질이 실험실에서는 효과적이지만 체내에서는 그 효과가 제한된다는 한계를 제시한다."
    },
    {
      "id": "R24",
      "type": "CAUSE",
      "otherName": "",
      "reason": "혈장 단백질의 흡착이 mRNA의 세포막 투과를 실제로 제한하는 원인이다."
    },
    {
      "id": "R25",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "양이온성 지질의 체내 전달 한계에 대응하여 이온화 지질이라는 대체 재료를 도입한다."
    },
    {
      "id": "R26",
      "type": "CAUSE",
      "otherName": "",
      "reason": "높은 수소 이온 농도가 이온화 지질의 양이온화를 일으키는 실제 화학적 작용을 나타낸다."
    },
    {
      "id": "R27",
      "type": "CAUSE",
      "otherName": "",
      "reason": "수소 이온을 적게 받아들이는 것이 이온화 지질의 전기적 중성화를 가져온다."
    },
    {
      "id": "R28",
      "type": "CAUSE",
      "otherName": "",
      "reason": "이온화 지질의 전기적 중성 상태가 혈장 단백질의 흡착을 방지하는 실제 작용 관계이다."
    },
    {
      "id": "R29",
      "type": "CONDITION",
      "otherName": "",
      "reason": "pH가 낮은 경우와 높은 경우에 따라 이온화 지질의 전하 상태와 흡착 여부가 달라진다."
    },
    {
      "id": "R30",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "pH에 따른 전하 변화 원리를 mRNA 결합과 중성 복합체 제조에 가져다 쓴다."
    },
    {
      "id": "R31",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "혈장 단백질의 흡착 여부라는 같은 기준에서 양이온성 지질과 중성 이온화 지질을 비교한다."
    },
    {
      "id": "R32",
      "type": "PROCESS",
      "otherName": "",
      "reason": "낮은 pH에서 결합시킨 산출물을 바탕으로 pH를 높여 중성 복합체를 만드는 다음 단계가 진행된다."
    },
    {
      "id": "R33",
      "type": "PROCESS",
      "otherName": "",
      "reason": "제조된 복합체가 다음 단계에서 수용체 결합과 내포 작용을 거쳐 세포 안으로 들어가는 순서이다."
    },
    {
      "id": "R34",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "복합체의 진입 방식으로 언급된 내포 작용이 무엇을 뜻하는지 풀어 설명하는 관계이다."
    },
    {
      "id": "R35",
      "type": "CAUSE",
      "otherName": "",
      "reason": "내포 작용이 세포질 안에 엔도솜 구조체를 형성하는 실제 작용을 나타낸다."
    },
    {
      "id": "R36",
      "type": "CAUSE",
      "otherName": "",
      "reason": "엔도솜 내부의 산성화가 엔도솜 막의 불안정화를 일으킨다."
    },
    {
      "id": "R37",
      "type": "CAUSE",
      "otherName": "",
      "reason": "엔도솜 막의 불안정화가 mRNA의 세포질 방출을 일으키는 원인이다."
    },
    {
      "id": "R38",
      "type": "PROCESS",
      "otherName": "",
      "reason": "세포질로 방출된 mRNA를 바탕으로 리보솜 결합과 단백질 합성 및 면역 반응의 다음 단계가 진행된다."
    },
    {
      "id": "R39",
      "type": "CAUSE",
      "otherName": "",
      "reason": "기억 세포의 생성이 인체에 바이러스 감염 대비 능력을 갖추게 하는 실제 결과로 이어진다."
    },
    {
      "id": "R40",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "앞서 설명한 mRNA와 리보솜의 단백질 합성 원리를 백신 mRNA의 작동에 적용한다."
    },
    {
      "id": "R41",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "기억 세포를 통해 재침입에 대비하는 일반 면역 원리를 mRNA 백신의 예방 효과에 적용한다."
    },
    {
      "id": "R42",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "mRNA 백신의 면역 유도 설명을 리보솜 결합과 단백질 합성 및 기억 세포 생성 과정으로 상세화한다."
    }
  ]
}

